/// Returns the next keyword if there is one.
fn next_if_keyword(&mut self) -> Option<Keyword> {
    let peeked = self.lexer.peek().cloned();
    if let Some(Ok(Token::Keyword(k))) = &peeked {
        self.lexer.next();
        Some(*k)
    } else {
        None
    }
}

